mapper.select:
SELECT COUNT(*)
  FROM tdm91_company_setup
 WHERE tdm91_company_id        = #{companyId}
   AND tdm91_start_date        = #{startDate}
   AND tdm91_company_setup_id != #{companySetupId}

SELECT tdm91_company_id
  FROM tdm91_company_setup
 WHERE tdm91_company_setup_id = #{companySetupId}

mapper.update:
UPDATE tdm91_company_setup
   SET tdm91_start_date         = #{row.startDate}
     , tdm91_cmnt_min_limit     = #{row.cmntMinLimit}
     , tdm91_batch_check_use_yn = #{row.batchCheckUseYn}
     , tdm91_batch_appr_use_yn  = #{row.batchApprUseYn}
     , tdm91_evid_file_check_yn = #{row.evidFileCheckYn}
     , tdm91_note               = #{row.note}
     , tdm91_upd_nm             = #{updName}
     , tdm91_upd_date           = f_sysdate()
 WHERE tdm91_company_setup_id = #{row.companySetupId}

mapper.delete:
DELETE FROM tdm91_company_setup
 WHERE tdm91_company_id = #{companyId}
   AND tdm91_company_setup_id IN
#{id}
